(function () {
  'use strict';

  // Offline QR generator for CafeKiosk kiosk links.
  // Fixed QR Version 8, error-correction level H. This comfortably supports
  // the localhost test URLs generated by CafeKiosk (up to 84 ASCII bytes).
  const VERSION = 8;
  const SIZE = VERSION * 4 + 17; // 49
  const DATA_CODEWORDS = 86;
  const ECC_PER_BLOCK = 26;
  const DATA_BLOCKS = [14, 14, 14, 14, 15, 15];
  const ALIGNMENT = [6, 24, 42];
  const FORMAT_EC_H = 2;
  const MASK = 0;

  const GF_EXP = new Array(512).fill(0);
  const GF_LOG = new Array(256).fill(0);
  (function initGalois() {
    let x = 1;
    for (let i = 0; i < 255; i += 1) {
      GF_EXP[i] = x;
      GF_LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11d;
    }
    for (let i = 255; i < 512; i += 1) GF_EXP[i] = GF_EXP[i - 255];
  })();

  function gfMul(a, b) {
    if (!a || !b) return 0;
    return GF_EXP[GF_LOG[a] + GF_LOG[b]];
  }

  function polyMul(a, b) {
    const out = new Array(a.length + b.length - 1).fill(0);
    for (let i = 0; i < a.length; i += 1) {
      for (let j = 0; j < b.length; j += 1) out[i + j] ^= gfMul(a[i], b[j]);
    }
    return out;
  }

  function generatorPoly(degree) {
    let poly = [1];
    for (let i = 0; i < degree; i += 1) poly = polyMul(poly, [1, GF_EXP[i]]);
    return poly;
  }

  const RS_GENERATOR = generatorPoly(ECC_PER_BLOCK);

  function rsRemainder(data) {
    const result = new Array(ECC_PER_BLOCK).fill(0);
    for (const value of data) {
      const factor = value ^ result[0];
      result.shift();
      result.push(0);
      for (let i = 0; i < ECC_PER_BLOCK; i += 1) {
        result[i] ^= gfMul(RS_GENERATOR[i + 1], factor);
      }
    }
    return result;
  }

  function utf8Bytes(text) {
    if (window.TextEncoder) return Array.from(new TextEncoder().encode(String(text)));
    return Array.from(unescape(encodeURIComponent(String(text)))).map(ch => ch.charCodeAt(0));
  }

  function appendBits(bits, value, length) {
    for (let i = length - 1; i >= 0; i -= 1) bits.push((value >>> i) & 1);
  }

  function createCodewords(text) {
    const bytes = utf8Bytes(text);
    if (bytes.length > 84) throw new Error('Kiosk URL is too long for the branded QR test format.');

    const bits = [];
    appendBits(bits, 0x4, 4); // Byte mode
    appendBits(bits, bytes.length, 8); // Version 1-9 character count
    bytes.forEach(byte => appendBits(bits, byte, 8));

    const maxBits = DATA_CODEWORDS * 8;
    for (let i = 0; i < Math.min(4, maxBits - bits.length); i += 1) bits.push(0);
    while (bits.length % 8) bits.push(0);

    const data = [];
    for (let i = 0; i < bits.length; i += 8) {
      let value = 0;
      for (let j = 0; j < 8; j += 1) value = (value << 1) | bits[i + j];
      data.push(value);
    }
    let pad = true;
    while (data.length < DATA_CODEWORDS) {
      data.push(pad ? 0xec : 0x11);
      pad = !pad;
    }

    const blocks = [];
    let offset = 0;
    for (const count of DATA_BLOCKS) {
      const blockData = data.slice(offset, offset + count);
      offset += count;
      blocks.push({ data: blockData, ecc: rsRemainder(blockData) });
    }

    const result = [];
    const maxData = Math.max(...DATA_BLOCKS);
    for (let i = 0; i < maxData; i += 1) {
      blocks.forEach(block => { if (i < block.data.length) result.push(block.data[i]); });
    }
    for (let i = 0; i < ECC_PER_BLOCK; i += 1) blocks.forEach(block => result.push(block.ecc[i]));
    return result;
  }

  function bchDigit(value) {
    let digit = 0;
    while (value) { digit += 1; value >>>= 1; }
    return digit;
  }

  function formatBits(data) {
    const G15 = 0x537;
    const MASK15 = 0x5412;
    let d = data << 10;
    while (bchDigit(d) - bchDigit(G15) >= 0) d ^= G15 << (bchDigit(d) - bchDigit(G15));
    return ((data << 10) | d) ^ MASK15;
  }

  function versionBits(version) {
    const G18 = 0x1f25;
    let d = version << 12;
    while (bchDigit(d) - bchDigit(G18) >= 0) d ^= G18 << (bchDigit(d) - bchDigit(G18));
    return (version << 12) | d;
  }

  function makeMatrix(text) {
    const matrix = Array.from({ length: SIZE }, () => new Array(SIZE).fill(null));

    function finder(row, col) {
      for (let r = -1; r <= 7; r += 1) {
        for (let c = -1; c <= 7; c += 1) {
          const rr = row + r, cc = col + c;
          if (rr < 0 || rr >= SIZE || cc < 0 || cc >= SIZE) continue;
          const dark = r >= 0 && r <= 6 && c >= 0 && c <= 6 &&
            (r === 0 || r === 6 || c === 0 || c === 6 || (r >= 2 && r <= 4 && c >= 2 && c <= 4));
          matrix[rr][cc] = dark;
        }
      }
    }

    finder(0, 0);
    finder(SIZE - 7, 0);
    finder(0, SIZE - 7);

    for (const row of ALIGNMENT) {
      for (const col of ALIGNMENT) {
        if (matrix[row][col] !== null) continue;
        for (let r = -2; r <= 2; r += 1) {
          for (let c = -2; c <= 2; c += 1) {
            matrix[row + r][col + c] = Math.max(Math.abs(r), Math.abs(c)) !== 1;
          }
        }
      }
    }

    for (let i = 8; i < SIZE - 8; i += 1) {
      if (matrix[i][6] === null) matrix[i][6] = i % 2 === 0;
      if (matrix[6][i] === null) matrix[6][i] = i % 2 === 0;
    }

    function setVersionInfo(test) {
      const bits = versionBits(VERSION);
      for (let i = 0; i < 18; i += 1) {
        const dark = !test && ((bits >>> i) & 1) === 1;
        matrix[Math.floor(i / 3)][i % 3 + SIZE - 11] = dark;
        matrix[i % 3 + SIZE - 11][Math.floor(i / 3)] = dark;
      }
    }

    function setFormatInfo(test) {
      const bits = formatBits((FORMAT_EC_H << 3) | MASK);
      for (let i = 0; i < 15; i += 1) {
        const dark = !test && ((bits >>> i) & 1) === 1;
        if (i < 6) matrix[i][8] = dark;
        else if (i < 8) matrix[i + 1][8] = dark;
        else matrix[SIZE - 15 + i][8] = dark;

        if (i < 8) matrix[8][SIZE - i - 1] = dark;
        else if (i < 9) matrix[8][15 - i] = dark;
        else matrix[8][15 - i - 1] = dark;
      }
      matrix[SIZE - 8][8] = !test;
    }

    setVersionInfo(true);
    setFormatInfo(true);

    const codewords = createCodewords(text);
    let row = SIZE - 1;
    let inc = -1;
    let byteIndex = 0;
    let bitIndex = 7;

    for (let col = SIZE - 1; col > 0; col -= 2) {
      if (col === 6) col -= 1;
      while (true) {
        for (let c = 0; c < 2; c += 1) {
          const targetCol = col - c;
          if (matrix[row][targetCol] !== null) continue;
          let dark = false;
          if (byteIndex < codewords.length) dark = ((codewords[byteIndex] >>> bitIndex) & 1) === 1;
          if ((row + targetCol) % 2 === 0) dark = !dark; // mask pattern 0
          matrix[row][targetCol] = dark;
          bitIndex -= 1;
          if (bitIndex < 0) { byteIndex += 1; bitIndex = 7; }
        }
        row += inc;
        if (row < 0 || row >= SIZE) {
          row -= inc;
          inc = -inc;
          break;
        }
      }
    }

    setVersionInfo(false);
    setFormatInfo(false);
    return matrix;
  }

  function drawLogo(ctx, canvas, logoUrl, size) {
    return new Promise(resolve => {
      const img = new Image();
      img.onload = function () {
        const cx = canvas.width / 2;
        const cy = canvas.height / 2;
        const s = size || Math.round(canvas.width * 0.17);
        ctx.save();
        ctx.beginPath();
        ctx.arc(cx, cy, s * 0.60, 0, Math.PI * 2);
        ctx.fillStyle = '#fffaf0';
        ctx.fill();
        ctx.lineWidth = Math.max(2, Math.round(canvas.width * 0.006));
        ctx.strokeStyle = '#6a472f';
        ctx.stroke();
        ctx.beginPath();
        ctx.arc(cx, cy, s * 0.50, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(img, cx - s / 2, cy - s / 2, s, s);
        ctx.restore();
        resolve();
      };
      img.onerror = resolve;
      img.src = logoUrl || '/Assets/images/logo.png';
    });
  }

  async function render(canvas, text, options = {}) {
    if (!canvas || typeof canvas.getContext !== 'function') throw new Error('QR canvas was not found.');
    const matrix = makeMatrix(String(text));
    const quiet = 4;
    const moduleCount = SIZE + quiet * 2;
    const targetSize = Number(options.size || 360);
    const modulePx = Math.max(4, Math.floor(targetSize / moduleCount));
    const actualSize = modulePx * moduleCount;
    canvas.width = actualSize;
    canvas.height = actualSize;

    const ctx = canvas.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = options.background || '#fffaf0';
    ctx.fillRect(0, 0, actualSize, actualSize);
    ctx.fillStyle = options.foreground || '#4c321f';

    for (let row = 0; row < SIZE; row += 1) {
      for (let col = 0; col < SIZE; col += 1) {
        if (!matrix[row][col]) continue;
        const x = (col + quiet) * modulePx;
        const y = (row + quiet) * modulePx;
        // Small rounding gives the cafe-themed dotted look while preserving scan reliability.
        const radius = Math.max(0, Math.min(modulePx * 0.24, 2));
        if (!radius) {
          ctx.fillRect(x, y, modulePx, modulePx);
        } else {
          const w = modulePx, h = modulePx;
          ctx.beginPath();
          ctx.moveTo(x + radius, y);
          ctx.arcTo(x + w, y, x + w, y + h, radius);
          ctx.arcTo(x + w, y + h, x, y + h, radius);
          ctx.arcTo(x, y + h, x, y, radius);
          ctx.arcTo(x, y, x + w, y, radius);
          ctx.closePath();
          ctx.fill();
        }
      }
    }

    await drawLogo(ctx, canvas, options.logoUrl || '/Assets/images/logo.png', Math.round(actualSize * 0.16));
    return canvas;
  }

  function download(canvas, filename) {
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = filename || 'cafekiosk-kiosk-qr.png';
    link.href = canvas.toDataURL('image/png');
    link.click();
  }

  window.CafeKioskQR = { render, download, makeMatrix };
})();
